const $=s=>document.querySelector(s),canvas=$('#world'),ctx=canvas.getContext('2d'),mini=$('#minimap'),mc=mini.getContext('2d');let expedition=new Expedition(),world=expedition.current,camera={x:world.player.x,y:world.player.y},keys={},started=false,paused=false,modal=false,modalKind=null,modalOpener=null,openingKey=null,last=0,nearest=null,hovered=null,mouse={x:0,y:0},zoom=1,mapOpen=false,frame=0,autosave=0,mapTarget=null,mapCache=null;const color={player:'#c0b68a',sanctuary:'#b5a77a',oak:'#7a9e8b',salt:'#7a9da8',north:'#a29cbb',red:'#aa6050',ash:'#b08d55',wild:'#8e9075',thorn:'#a48d9f'};
