let sw=innerWidth,sh=innerHeight,dpr=Math.min(devicePixelRatio||1,2);function resize(){sw=innerWidth;sh=innerHeight;canvas.width=sw*dpr;canvas.height=sh*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);zoom=sw<700?.8:1;}addEventListener('resize',resize);resize();
function connect(){world.onDetention=()=>arrestDialog();world.onEvent=(text,event)=>{if(!world.eventObservable(event))return;const div=document.createElement('div');div.textContent=text;$('#feed').prepend(div);while($('#feed').children.length>4)$('#feed').lastChild.remove();setTimeout(()=>div.remove(),18000);};world.onAction=()=>toast('Действие завершено');world.onDeath=()=>{if(world.dungeonSpec)expedition.pendingDeath=true;else {deathScreen();save();}};}connect();
function toast(t){$('#toast').textContent=t;clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').textContent='',4000);}function save(){try{const old=localStorage.getItem(SAVE_KEY);let oldVersion=0;try{oldVersion=JSON.parse(old)?.version||0;}catch{}if(old&&oldVersion!==3&&!localStorage.getItem(SAVE_KEY+'-before-lore'))localStorage.setItem(SAVE_KEY+'-before-lore',old);if(old&&oldVersion===2&&!JSON.parse(old).interiorRevision&&!localStorage.getItem(SAVE_KEY+'-before-interiors'))localStorage.setItem(SAVE_KEY+'-before-interiors',old);localStorage.setItem(SAVE_KEY,expedition.save());}catch{toast('Не удалось сохранить: хранилище браузера недоступно.');}}
let pendingSave=null;function scheduleSave(){if(pendingSave!==null)return;const callback=()=>{pendingSave=null;if(started)save();};pendingSave=typeof requestIdleCallback==='function'?requestIdleCallback(callback,{timeout:2000}):setTimeout(callback,0);}
function start(load=false,{seed=null,forceCathedral=false,campaign=false,migrate=false}={}){if(load&&!migrate){try{const old=JSON.parse(localStorage.getItem(SAVE_KEY));if(old?.version===2){migrationMenu();return;}}catch{}}if(pendingSave!==null){if(typeof cancelIdleCallback==='function')cancelIdleCallback(pendingSave);clearTimeout(pendingSave);pendingSave=null;}pathService?.dispose();assets?.dispose();keys={};nearest=null;mapTarget=null;autosave=0;paused=false;modal=false;mapOpen=false;$('#modal').classList.add('hidden');$('#feed').replaceChildren();$('#pause').textContent='Ⅱ';if(load){try{expedition=Expedition.restore(localStorage.getItem(SAVE_KEY));world=expedition.current;}catch{toast('Сохранение повреждено. Начинаем новый мир.');expedition=new Expedition(new World($('#seed').value));world=expedition.current;}}else {expedition=new Expedition(new World(seed||$('#seed').value||'734291'));world=expedition.current;}if(!load&&campaign)startCampaign(world);lastCampaignStage=null;connect();assets=new RenderAssets(world);pathService=new PathService(world);const preview=new URLSearchParams(location.search).get('start');const z=world.places.find(z=>z.id===preview&&['oak','salt','north'].includes(z.id));if(z&&!load&&!forceCathedral&&!campaign){world.player.x=z.x*TILE;world.player.y=(z.y+2)*TILE;}mapCache=null;camera={x:world.player.x,y:world.player.y};started=true;$('#welcome').classList.add('hidden');world.log(load?'Путешествие продолжено: '+(world.dungeonSpec?.name||world.placeAt(world.player)?.name||'дикие земли')+'.':z&&!forceCathedral?'Вы прибыли в '+z.name+'. '+(z.kind==='village'?'Староста и местный торговец помогут освоиться.':z.kind==='town'?'Бургомистр принимает в ратуше.':'Король принимает в замке; магазины окружают центральную площадь.'):'Вы прибыли во двор собора. Библиотека слева, тренировочный зал справа, Софос — в северном зале.');save();if(!load&&campaign){setJournalCollapsed(false);campaignPanel();}if(expedition.surface.deathReport&&!expedition.surface.deathReport.acknowledged)deathScreen();}
$('#begin').onclick=()=>start();$('#continue').onclick=()=>start(true);try{if(localStorage.getItem(SAVE_KEY))$('#continue').classList.remove('hidden');}catch{}
function open(content,kind='interaction'){if(expedition.surface.deathReport&&!expedition.surface.deathReport.acknowledged&&kind!=='death')return;modalOpener=openingKey||(modal?modalOpener:kind);modalKind=kind;modal=true;mapOpen=kind==='map';keys={};$('#modal-content').innerHTML=content;$('.modal-card').scrollTop=0;$('#modal').classList.remove('hidden');}
function openWindow(kind,content){campaignEvent(expedition.surface,'window',{kind});open(content,kind);}
function close(){if(expedition.surface.deathReport&&!expedition.surface.deathReport.acknowledged)return;modal=false;modalKind=null;modalOpener=null;keys={};$('#modal').classList.add('hidden');mapOpen=false;if(started)save();}
function toggleWindow(kind,render){if(!started)return;if(modal&&(modalKind===kind||modalOpener===kind)){close();return;}openingKey=kind;try{render();}finally{openingKey=null;}}
