function button(text,action){const b=document.createElement('button');b.textContent=text;b.onclick=action;return b;}
const lore=[['Я готов отправиться на поиски артефакта.','В старых руинах к юго-западу лежит Осколок рассвета. Верни его сюда, в мои покои. За лесом следят Красные лисы. Будь осторожен.'],['Что это за собор?','Когда-то здесь звонили семь колоколов. Теперь остался один. Пока звучит он, ни зверь, ни разбойник не переступит порог с оружием.'],['Почему только ты умеешь колдовать?','Я последний, кто помнит язык камня. Мой дар не передаётся оружию или людям. Тебе предстоит полагаться на сталь и собственные ноги.'],['Расскажи о городах.','Дубовый предел на западе, Соляная пристань на востоке и Северный дозор живут своим трудом. Их стража защищает местных жителей.'],['Кто хозяйничает в лесах?','Красные лисы и Пепельные псы. Они ненавидят друг друга почти так же сильно, как чужие караваны.'],['Что происходит ночью?','Люди возвращаются домой. На улицах остаётся стража, а звери подходят ближе к дорогам. Время здесь идёт для всех.'],['Откуда у рыбаков рыба?','Из воды. Пока рыбак не дойдёт до озера и не закончит ловлю, в его сумке нет ни одной рыбы. Можешь проверить сам.'],['Если я погибну?','После смерти придёт другой странник с чистой репутацией. Тело погибшего останется в лесу, пока его не найдут мародёры; вещи, принятые городской стражей, новому человеку не отдадут.'],['Где потренироваться?','В восточном крыле есть тренировочный зал со стоячими и движущимися манекенами. Удары по ним безопасны. Следи за выносливостью.'],['Как восстановить здоровье?','Съешь паёк, мясо или рыбу из инвентаря. У рыночных торговцев продаются припасы.'],['Что находится в библиотеке?','Правила этого мира, записи о твоих встречах, перечень находок. Полка у западной стены всегда открыта.'],['Тебе бывает одиноко?','Иногда. Но тишина редко пуста. В ней слышно, как дождь учится говорить с крышей.'],['Что ты думаешь о дорогах?','Каждая дорога — обещание встречи. Не все обещания добрые.'],['Можно ли доверять торговцам?','Проверь их товар и решай сам. Они ходят между рынками, а их сумки могут заинтересовать разбойников.'],['Как найти руины?','Выйди через южные ворота, затем иди на запад и на юг. На карте руины отмечены ромбом. Клавиша M развернёт карту.'],['Я принёс Осколок рассвета.','Покажи мне его.']];
function deathScreen(){open('<div id="death-report"></div>','death');$('#modal').classList.add('death-screen');renderDeath($('#death-report'),expedition.surface,{continueLife:()=>{expedition.surface.deathReport.acknowledged=true;$('#modal').classList.remove('death-screen');close();hud();save();}});}
