function wizard(message=null){const surface=expedition.surface,lesson=campaignLesson(surface),primary=[],topics=[],hasRelic=RELIC_KEYS.some(k=>world.player.inventory[k]>0&&!surface.returnedRelics.includes(k));const add=(label,run)=>primary.push({label,run});let view;
 if(hasRelic)add('Передать найденные реликвии',()=>wizard(returnRelics()));
 if(lesson&&['welcome','departure'].includes(lesson.id))add('Продолжить историю',()=>{campaignWizard(surface);save();hud();wizard();});
 if(!surface.quest&&!lesson)add('Начать поиски реликвий',()=>{const message=beginRelicHunt(surface);save();wizard(message);});
 topics.push({id:'hunt',label:'Поручения Софоса',greeting:'Вещи опасны, даже если их нынешний хозяин считает иначе. Не проверяй, что они умеют.',render:body=>renderHunt(body,surface,{select:t=>mapTarget=t,close})});
 const remaining=surface.landmarks.find(l=>l.id!=='supply'&&!surface.returnedRelics.includes(l.item));if(remaining&&(surface.quest||['artifact','return'].includes(lesson?.id)))add('Где искать следующую реликвию?',say=>{mapTarget={...remaining,name:remaining.name};say('Отметил цель: '+remaining.name+'. Открой карту M, чтобы выбрать дорогу.');});
 if(surface.campaign)add('Мой путь · T',campaignPanel);
 topics.push({id:'world',label:'О мире',greeting:'Что тебя интересует?',render:body=>{for(const [title,indices]of [['Собор и Софос',[1,2,10,11]],['Города и люди',[3,4,6,13]],['Дорога и выживание',[5,7,8,9,12,14]]]){const group=document.createElement('details');group.className='compact-choice';const summary=document.createElement('summary');summary.textContent=title;group.append(summary);group.addEventListener('toggle',()=>{if(group.open)for(const other of body.querySelectorAll(':scope > details'))if(other!==group)other.open=false;});const list=document.createElement('div');list.className='conversation-actions';for(const i of indices)list.append(button(lore[i][0],()=>{let text=lore[i][1];if(i===3)text=surface.cities.map(z=>z.name+' — '+(z.layoutName||'поселение')).join('; ')+'.';if(i===14)text='Ищи '+surface.places.find(z=>z.id==='ruins').name+' на карте M. Дороги зависят от зерна мира.';view.say(text);}));group.append(list);body.append(group);}}});
 if(lesson&&['welcome','orientation','library','sword','moving','bow','craft','departure'].includes(lesson.id)&&(lesson.id==='craft'?!(world.player.inventory.cloth>0):lesson.id==='bow'?!(world.player.inventory.bow>0)||world.player.inventory.arrow<8:!(world.player.inventory.sword>0)))topics.push({id:'training',label:'Учебные припасы',render:body=>{const p=document.createElement('p');p.textContent='Если для текущего урока не хватает материалов или снаряжения, Софос поделится своим запасом.';body.append(p,button('Попросить недостающее',()=>{view.say(campaignTrainingSupplies(surface).message);save();}));}});
 if(!primary.length)add('Поговорим о мире',()=>view.show('world'));open('<div id="conversation"></div>');view=renderConversation($('#conversation'),{eyebrow:'ЗАЛ СОФОСА',title:'Волшебник Софос',greeting:message||(surface.returnedRelics.length>=relicCatalog(surface).length?'Все вещи на месте. Я закрою внутреннюю дверь. Возвращайся, если понадобится помощь людям.':lesson?lesson.text:surface.campaign?.status==='completed'?'Ты вернул свет. Теперь выбирай собственную дорогу.':'В дальних местах остались вещи, с которыми нельзя обращаться как с обыкновенной добычей. Принеси их мне целиком. Не обещаю тебе их силы — только плату за дорогу.'),primary,topics});}

function returnRelics(){const active=world.campaign?.status==='active',result=world.depositRelics();save();hud();if(active&&world.campaign?.status==='completed')return 'Ты вернул свет, странник. Кампания «Колокол и рассвет» завершена. Реликвия заняла пьедестал; прими '+result.reward+' золотых. Теперь выбирай собственный путь: весь мир открыт, а всё нажитое остаётся с тобой.';return result.count?result.receipts.join(' ')+' Реликвий возвращено: '+result.total+'/'+relicCatalog(expedition.surface).length+'. Прими '+result.reward+' золотых.':'У тебя пока нет новых реликвий для моих покоев.';}

function crafting(){openWindow('craft','<div id="craft-panel"></div>');renderCraftPanel($('#craft-panel'),world,{changed:()=>{hud();save();},close,notify:toast});}
function contracts(city=world.inCity(world.player)?.id){openWindow('contracts','<div id="contract-panel"></div>');renderContracts($('#contract-panel'),world,city,{changed:()=>{hud();save();},notify:toast,projects:()=>projectsPanel(city),select:target=>{mapTarget=target;toast('Ориентир установлен: '+target.name);}});}
