function captiveTalk(e){open('<div class="eyebrow">ПЛЕННЫЙ ПОДМАСТЕРЬЕ</div><h1>'+e.name+'</h1><p>'+(e.captive?'«Развяжи мне руки. Если смогу выйти, пойду за тобой к городскому складу».':e.rescued?'«Спасибо, ты вернул меня домой. Обратись к квартирмейстеру за наградой».':'«Я иду за тобой. Не убегай далеко и доведи меня до родного склада».')+'</p><div id="rescue-actions" class="actions"></div>');if(e.captive)$('#rescue-actions').append(button('Развязать путы · 4 секунды',()=>{const result=beginRescue(world,e);toast(result.message);if(result.ok)close();}));else $('#rescue-actions').append(button('Отметить родной склад',()=>{mapTarget={name:'Родной склад · '+world.factionName(e.rescueCity),...e.home};close();}));}
function inventory(){world.normalizeEquipment();const p=world.player;openWindow('inventory','<div class="eyebrow">СНАРЯЖЕНИЕ СТРАННИКА</div><h1>Дорожная сумка</h1><div class="stats"><span>Здоровье: '+Math.ceil(p.hp)+'/100</span><span>Выносливость: '+Math.ceil(p.stamina)+'/'+(p.maxStamina||MAX_STAMINA)+'</span><span>Золото: '+(p.inventory.gold||0)+'</span><span>В руках: '+(ITEMS[p.weapon]?.name||'Без оружия')+'</span></div><div class="weapon-slots" id="weapons"></div><div id="items"></div><details class="compact-help"><summary>Как настроить оружие и снаряжение</summary><p>Q или кнопка ↔ на панели — быстро взять оружие из другого слота. Для дальнего боя нужны лук и стрелы. В ближний слот можно поставить меч, топор или молот. R — достать / убрать. С обнажённым оружием стража предупредит дважды и атакует, если его не убрать.</p></details>');for(const [mode,label,choices]of [['melee','Ближний слот',['sword','axe','hammer']],['ranged','Дальний слот',['bow']]]){const box=document.createElement('label');box.className='weapon-slot'+(p.weaponMode===mode?' active':'');const title=document.createElement('span');title.textContent=label;const select=document.createElement('select');select.id='slot-'+mode;select.setAttribute('aria-label',label);const empty=document.createElement('option');empty.value='';empty.textContent='Пустой слот';select.append(empty);for(const key of choices){const option=document.createElement('option');option.value=key;option.textContent=ITEMS[key].name+(!(p.inventory[key]>0)?' · нет в сумке':'');option.disabled=!(p.inventory[key]>0);select.append(option);}select.value=p.equipment[mode]||'';select.onchange=()=>{const result=world.equip(mode,select.value||null);if(!result.ok)toast(result.message);inventory();};box.append(title,select);const take=button(p.weaponMode===mode?'В руках':'Взять в руки',()=>{if(!p.equipment[mode]||!(p.inventory[p.equipment[mode]]>0)){toast('Слот пуст или оружия нет в сумке');return;}p.weaponMode=mode;world.normalizeEquipment();inventory();});take.disabled=p.weaponMode===mode;box.append(take);$('#weapons').append(box);}itemRows(p.inventory,$('#items'),k=>{if(USE_EFFECTS[k]){const result=useSupply(world,k);toast(result.message);inventory();return;}if(k==='breathSuit'){const result=toggleBreathSuit(world);toast(result.message);inventory();return;}if(k==='torch'){world.player.inventory.torch--;world.player.torchUntil=world.time+90;toast('Факел зажжён на 90 игровых минут.');inventory();return;}if(['ration','fish','meat','herb'].includes(k)){if(p.hp>=100){toast('Здоровье уже восстановлено.');return;}p.inventory[k]--;if(!p.inventory[k])delete p.inventory[k];p.hp=Math.min(100,p.hp+({ration:35,fish:20,meat:25,herb:40})[k]);inventory();}},k=>USE_EFFECTS[k]||['ration','fish','meat','herb','torch','breathSuit'].includes(k)?(k==='breathSuit'?(p.breathSuitWorn?'Снять':'Надеть'):'Использовать'):'');$('#items').after(button('Открыть ремесло · C',crafting));for(const[slot,label,choices]of [['body','Одежда и броня',['coat','travelCoat','armor']],['offhand','Щит',['shield']]]){if(!choices.some(k=>p.inventory[k]>0))continue;const box=document.createElement('div');box.className='weapon-slot';box.append(document.createTextNode(label));for(const key of choices)if(p.inventory[key]>0)box.append(button((p.gear?.[slot]===key?'✓ ':'')+ITEMS[key].name,()=>{equipGear(world,slot,p.gear?.[slot]===key?null:key);inventory();}));$('#weapons').append(box);}}
function switchWeapon(){if(!started||modal)return;const result=world.switchWeapon();toast(result.message);hud();}

function itemRows(inv,el,action,label){const entries=Object.entries(inv).filter(([,v])=>v>0);if(!entries.length)el.innerHTML='<div class="empty">Здесь ничего нет.</div>';for(const [k,v]of entries){const row=document.createElement('div');row.className='item-row';const span=document.createElement('span');span.textContent=(ITEMS[k]?.icon||'◇')+'  '+(ITEMS[k]?.name||k)+' × '+v;if(ITEMS[k]?.description){const desc=document.createElement('small');desc.className='item-description';desc.textContent=ITEMS[k].description;span.append(desc);}row.append(span);const text=label?.(k);if(text)row.append(button(text,()=>action(k)));el.append(row);}}
function arrestDialog(){const d=world.detention;if(!d)return;const verdict=sentence(world,d.city);if(!verdict)return;const penniless=(world.player.inventory.gold||0)<verdict.amount;open('<div class="eyebrow">СТРАЖА · '+world.factionName(d.city)+'</div><h1>Вы задержаны</h1><p>Преступление: '+verdict.crime+'.</p><p>'+(verdict.kind==='fine'?(penniless?'«Денег нет? Проваливай. Но во второй раз отправишься в тюрьму».':'«За нарушение порядка — штраф 35 золотых. Заплати и убери оружие».'):'«Штрафом не отделаться. Сдавай оружие и вещи — я забираю тебя в тюрьму».')+'</p><div id="arrest-actions" class="actions"></div>');$('#arrest-actions').append(button(verdict.kind==='fine'?(penniless?'Выслушать предупреждение и уйти':'Заплатить 35 золотых'):'Подчиниться · отправиться в тюрьму',()=>{const result=settleArrest(world,'accept');close();if(!result.ok)toast(result.message);camera={x:world.player.x,y:world.player.y};hud();}),button('Отказываюсь. Буду драться до смерти',()=>{settleArrest(world,'fight');close();}));}
function cellDialog(cell){open('<div class="eyebrow">'+world.factionName(cell.city)+' · МЕСТО ЗАКЛЮЧЕНИЯ</div><h1>Тюремная решётка</h1><p>Камеру можно открыть ключом тюремщика. Навыка взлома замков пока нет.</p><p>'+(world.player.imprisoned?'Снаряжение изъято. Спрятанный заранее ключ остаётся при вас. Без него можно спровоцировать тюремщика: он откроет дверь и встанет в проходе. ЛКМ / пробел — удары кулаками; вооружённый и бронированный противник гораздо сильнее.':'Заключённые помнят свои цели: убийцы поднимут бунт, воры побегут к бандитам, пьяницы переждут стражу.')+'</p><div id="cell-actions" class="actions"></div>');$('#cell-actions').append(button('Открыть ключом',()=>{const result=openCell(world,cell.id);if(result.ok)close();else toast(result.message);}));if(world.player.imprisoned?.cellId===cell.id)$('#cell-actions').append(button('Спровоцировать тюремщика на драку',()=>{const result=provokeJailer(world);if(result.ok)close();else toast(result.message);}));}
function loot(c){open('<div id="loot-panel"></div>');renderLootPanel($('#loot-panel'),world,c,{onChange:()=>{hud();save();},onTakeAll:close,onButcher:source=>{world.player.action={corpse:source.obj.id,remaining:3};close();}});}
function trade(e,tab='buy',message='',query='',scroll=0){campaignEvent(world,'talk',{city:e.faction});const rule=TRADE[e.role];if(!rule)return townTalk(e);open('<div class="commerce"><div class="eyebrow">'+ROLES[e.role]+' · '+world.factionName(e.faction)+'</div><h1>'+e.name+'</h1><div class="trade-header"><span>У вас '+(world.player.inventory.gold||0)+' зол.</span><span>У мастера '+(e.inventory.gold||0)+' зол.</span><button id="town-task" class="text-button">Разговор →</button></div><div class="tabs" id="trade-tabs"></div><input id="trade-search" class="panel-search" aria-label="Найти товар" placeholder="Найти товар"><p class="panel-feedback" id="trade-feedback" role="status"></p><div id="trade-items" class="panel-list"></div></div>');const feedback=$('#trade-feedback'),search=$('#trade-search'),list=$('#trade-items');feedback.textContent=message;search.value=query;const paint=()=>{list.replaceChildren();const buy=tab==='buy',inventory=buy?e.inventory:world.player.inventory,keys=buy?rule.sells:rule.buys;const stock=Object.fromEntries(Object.entries(inventory).filter(([k,n])=>n>0&&keys.includes(k)&&(ITEMS[k]?.name||k).toLowerCase().includes(search.value.toLowerCase())));if(!Object.keys(stock).length){const empty=document.createElement('p');empty.className='empty';empty.textContent=search.value?'Товаров с таким названием нет.':buy?'У торговца пока нет товаров на продажу.':'В сумке нет вещей, которые интересуют этого торговца.';list.append(empty);return;}itemRows(stock,list,k=>{const result=world.trade(e,k,buy);if(!result.ok)feedback.textContent=result.message;else{hud();save();trade(e,tab,(buy?'Куплено: ':'Продано: ')+ITEMS[k].name,search.value,list.scrollTop);}},k=>(buy?'Купить · ':'Продать · ')+tradePrice(world,e,k,buy)+' зол.');};for(const [id,label]of [['buy','Купить'],['sell','Продать']]){const b=button(label,()=>trade(e,id));b.classList.toggle('selected',tab===id);b.setAttribute('aria-pressed',String(tab===id));$('#trade-tabs').append(b);}search.oninput=paint;$('#town-task').onclick=()=>townTalk(e);paint();list.scrollTop=scroll;}

const townGreetings={carpenter:'Строю городские улучшения из припасов, которые принесут квартирмейстеру. Днём работаю на месте, ночью отдыхаю. Без материалов нового арсенала или лечебницы не будет.',grainFarmer:'Собираю зерно и хмель с полей. Унесу урожай на склад, оттуда его заберут мельник и пивовар.',miller:'Сначала схожу на склад за зерном, потом смелю муку и верну готовые мешки. Из воздуха мука не появляется.',baker:'Мне нужны мука и мёд. Пеку хлеб в печи, затем несу его на склад. Купить хлеб можно у трактирщика.',brewer:'Беру зерно и хмель на складе и варю эль. Каждый готовый кувшин — результат варки.',beekeeper:'Ухаживаю за лесной пасекой. Собираю мёд и воск, потом несу их в город. Ульям нужно время, чтобы снова наполниться.',tanner:'Дублю настоящие шкуры. Полученная кожа идёт на плащи и щиты.',healer:'Готовлю мазь из трав и мёда. Если рядом раненый стражник, отнесу ему лекарство и перевяжу рану.',king:'Мои поручения касаются безопасности трактов и дальних руин. За верную службу корона платит щедро.',herald:'Слушайте последние вести! Обозы идут по трактам, чумы в городе пока нет.',tailor:'Из настоящего льна на станке получается полотно, из ткани и кожи я шью дорожные плащи.',farmer:'Собираю лён на поле и несу волокно на склад для ткачей.',citizen:'Я здесь живу и торговлей не занимаюсь. За поручениями обратись к старосте или бургомистру, а местные мастера работают в своих лавках.',guard:'Ворота и улицы под охраной. За стенами на караваны охотятся разбойники.',archer:'Моя стрела достанет врага раньше, чем он подойдёт к воротам.',fisher:'Улов отдаю на городской склад. Пока не закончу ловлю, рыбы в сумке не будет.',forester:'Сначала рублю дерево и складываю брёвна на земле, вечером несу их на склад. С тушами та же история: нужно разделать.',hunter:'Я выслеживаю дичь за стенами. Лесники помогают разделывать туши.',miner:'Выбираю руду в каменоломне и несу её на склад. Из неё кузнец делает оружие.',mayor:'У города есть дела в лесах и на дальних трактах. Выбирай поручение, которое тебе по силам.',quartermaster:'Принимаю поставки и храню вещи, которые стража сняла с тел. Сюда же приходят сопровождающие караваны.',merchant:'За следующими воротами нас ждёт покупатель. Помоги охране — но держись рядом до самого прибытия.'};
function loreTalk(e,message=null){let view;const primary=[];let greeting='';if(e.race==='arctarian'){greeting=e.role==='arctRescuer'?'Огромный безглазый хозяин опускается на колено, чтобы быть с вами вровень. Он показывает на свою грудь, затем на закрытую оболочку. Слова вам незнакомы.':'Мастер отвечает низким переливчатым звуком. Он освобождает место рядом и раскрывает ладони. Общих слов у вас нет.';if(e.role==='arctRescuer'&&!(world.player.inventory.breathSuit>0))primary.push({label:'Принять предложенную оболочку',run:()=>{const gift=acceptBreathSuit(world,e);save();hud();loreTalk(e,gift.message);}});if(world.player.inventory.breathSuit>0)primary.push({label:world.player.breathSuitWorn?'Открыть лицевую оболочку':'Сомкнуть швы одеяния',run:()=>{const r=toggleBreathSuit(world);save();loreTalk(e,r.message);}});primary.push({label:'Показать на фиолетовую густоту',run:say=>say('Он бережно прижимает края вашей оболочки друг к другу и показывает на каменную черту. Затем обводит пальцем низину. Вы понимаете жест, но не слова.')});}else if(e.role==='fairy'){greeting='Крылатая замирает над землёй. Голос похож на шорох тонкой ткани; она смотрит на всадников, прежде чем взглянуть на вас.';primary.push({label:'Показать пустые руки',run:say=>say('Она чуть опускает плечи и возвращается к порванному ремню. Ни копья, ни меча у неё нет.')},{label:'Указать на синий огонь',run:say=>say('Крылатая качает головой и указывает в сторону от стоянки. Один из всадников уже смотрит сюда.')});}else{greeting='«Око бережёт нас. Я не отдам его человеку из башни». Смотритель закрывает собой тёмное стекло. На рукояти молота белеют пальцы.';primary.push({label:'Софос велит забрать опасную вещь',run:say=>say('«Пусть придёт сам. Это всё, что у нас осталось». Он отступает к стене, не опуская оружия.')} );}open('<div id="conversation"></div>');view=renderConversation($('#conversation'),{eyebrow:world.factionName(e.faction),title:e.name,greeting:message||greeting,primary});}
function observation(site){const r=observeSite(world,site);if(!r.ok)return toast(r.message);open('<div id="observation"></div>');const root=$('#observation');for(const[tag,text]of [['div','ЗАРИСОВКА СТРАННИКА'],['h1',site.title],['p',r.message]]){const n=document.createElement(tag);n.textContent=text;root.append(n);}save();}
function observationNotes(){const w=expedition.surface;open('<div id="observation-notes"></div>');const root=$('#observation-notes'),h=document.createElement('h1');h.textContent='Зарисовки и следы';root.append(h);const notes=w.loreState?.notes||[];if(!notes.length){const p=document.createElement('p');p.textContent='Пока нет записей. Осматривайте необычные места через E.';root.append(p);}for(const id of notes){const site=w.loreSites?.find(s=>s.id===id);if(!site)continue;const d=document.createElement('details');d.className='compact-choice';const t=document.createElement('summary'),p=document.createElement('p');t.textContent=site.title;p.textContent=site.text;d.append(t,p);root.append(d);}}
function relicJournal(){open('<div class="eyebrow">ПОРУЧЕНИЯ СОФОСА</div><h1>Вещи, которым нужен покой</h1><div id="hunt-panel"></div>');renderHunt($('#hunt-panel'),expedition.surface,{select:t=>mapTarget=t,close});}
function townTalk(e,message=null){if(e.loreActor)return loreTalk(e,message);campaignEvent(world,'talk',{city:e.faction});if(e.role==='captive')return captiveTalk(e);if(world.detention?.guard===e.id)return arrestDialog();const offers=e.role==='king'?world.royalOffers(e):questOffers(e),lesson=campaignSupplyOffer(world,e.faction);if(e.role==='quartermaster'&&lesson)offers.unshift(lesson);const plan=conversationPlan(world,e,offers),full=townGreetings[e.role]||TRADE[e.role]?.text||'Каждый здесь занят своим делом.',primary=[],topics=[],add=(label,run)=>primary.push({label,run});let view;
 const rerender=text=>{save();hud();townTalk(e,text);};
 if(plan.ready.length)add('Сдать поручения · '+plan.ready.length,()=>rerender(world.completeQuests(e)));
 if(TRADE[e.role]&&!e.noTrade)add('Посмотреть товары',()=>trade(e));
 if(e.role==='quartermaster'){add('Заказы и экспедиции',()=>contracts(e.faction));add('Городские проекты',()=>projectsPanel(e.faction));}
 if(e.role==='cook')add('Ночлег с едой · '+servicePrice(world,e,'rest')+' зол.',say=>{const r=beginInnRest(world,e);if(r.ok){close();save();}else say(r.message);});
 if(['healer','herbalist'].includes(e.role)&&world.player.hp<world.player.maxHp)add('Лечение · '+servicePrice(world,e,'heal')+' зол.',say=>{const r=clinicHeal(world,e);if(r.ok)rerender(r.message);else say(r.message);});
 if(e.role==='hunter')add((e.companion?.active?'Продлить контракт':'Нанять спутника')+' · '+hirePrice(world,e)+' зол. / день',say=>{const r=hireCompanion(world,e);if(r.ok)rerender(r.message);else say(r.message);});
 if(e.role==='herald')add('Последние вести',say=>say(world.heraldNews(e.faction).join(' ')));
 add('Где найти человека или место?',()=>cityGuideDialog(e));
 if(plan.hasQuests&&e.role!=='quartermaster')add(e.role==='king'?'Королевские поручения':'Есть ли работа?',()=>view.show('quests'));if(plan.hasQuests&&e.role!=='quartermaster')topics.push({id:'quests',label:'Поручения'+(plan.available.length?' · '+plan.available.length:''),render:body=>renderQuestChoices(body,world,plan,{accept:q=>{const text=world.acceptQuest(q),target=world.places.find(z=>z.id===(q.place||q.destination));if(target)mapTarget={name:target.name,x:target.x*TILE,y:target.y*TILE};townTalk(e,text);save();},select:()=>journal()})});
 topics.push({id:'local',label:'О городе',greeting:'Что хочешь узнать о городе?',render:(body,say)=>{detailHelp(body,'О своей работе',full);const m=cityMemory(world,e.faction),r=warrant(world,e.faction);detailHelp(body,'Моя репутация',standing(world,e.faction).title+' · '+m.reputation+'. '+(r?'Розыск: '+r.name+'.':'Розыска нет.'));detailHelp(body,'Как устроены поселения','Король и замок есть в большом городе. В обычном городе — ратуша, в деревне один торговец. Местные подскажут дорогу к нужному человеку.');if((e.jailer||e.keyHolder)&&e.inventory['jailKey_'+e.faction]>0){const d=detailHelp(body,'Рискованные действия','Кражу ключа заметят, если подойти открыто.');d.append(button('Попытаться стащить ключ',()=>{say(stealPrisonKey(world,e).message||'Ключ спрятан в сумке.');save();}));}const stock=world.storages[e.faction];if(['quartermaster','guard','archer'].includes(e.role)&&stock&&Object.values(stock).some(n=>n>0))body.append(button('Получить вещи из хранилища',()=>{world.loot(world.player,{inventory:stock});world.storages[e.faction]={};rerender('Вещи переданы.');}));}});
 open('<div id="conversation"></div>');view=renderConversation($('#conversation'),{eyebrow:(ROLES[e.role]||'ЖИТЕЛЬ')+' · '+world.factionName(e.faction),title:e.name,greeting:message||full.match(/^[^.!?]+[.!?]?/)[0],primary,topics});}
function cityGuideDialog(e){open('<div class="eyebrow">'+world.factionName(e.faction)+'</div><h1>Как пройти?</h1><button class="text-button" id="guide-back">← К разговору</button><div id="city-guide"></div>');$('#guide-back').onclick=()=>townTalk(e);renderCityGuide($('#city-guide'),world,e);}

function library(tab='guide'){openWindow('library','<div class="eyebrow">БИБЛИОТЕКА СОБОРА · ХРОНИКИ 0.27 · АЛЬФА 9</div><h1>Книга странника</h1><div class="tabs" id="lib-tabs"></div><div class="codex" id="codex"></div>');[['guide','Как играть'],['bestiary','Бестиарий'],['finds','Находки'],['world','Живой мир']].forEach(([id,t])=>$('#lib-tabs').append(button(t,()=>library(id))));const data={guide:'<h3>Ремесло, лагеря и заказы</h3><p>C открывает ремесло и умения. Базовые рецепты работают вручную, остальные требуют очага, кузницы, склада, ткацкой или травной мастерской. Изготовление идёт в реальном времени; X отменяет работу и возвращает сырьё. Готовые предметы дают опыт и открывают сложные рецепты. Одежду и щит можно надеть в инвентаре I.</p><p>Снаружи поселений можно разбить лагерь из свёртка: кнопка находится в окне C. E у лагеря — сундук, отдых, топливо и сворачивание; C рядом с горящим костром — готовка. Сундук могут ограбить бандиты. На B или E у городской доски доступны заказы, зависящие от складских запасов, ремесленные поручения, обход стоянок и спасение пленных. Контракты сдаёт квартирмейстер, награда расходует казну. Подмастерья нужно освободить и действительно проводить домой; погибший пленник не возрождается.</p><h3>Городская память и тюрьмы</h3><p>После двух предупреждений за обнажённое оружие объявляют розыск на игровой час. Уберите оружие: стражник подойдёт и предложит штраф или тюрьму. Первое нарушение стоит 35 золотых; без денег отпустят. Повторное нарушение и убийство ведут в камеру. История и репутация — в журнале J. Городская стража не выходит за границы; дорожный дозор может вмешаться на тракте.</p><p>Ключ можно заранее стащить у спокойного тюремщика: подойдите со спины с убранным оружием и поговорите E. В камере E у решётки — открыть ключом или спровоцировать охранника. При провокации дверь откроется только после его подхода; он блокирует проход. Без вещей ЛКМ / пробел — удар кулаком. Проигрыш возвращает в запертую камеру. Вещи можно забрать из сундука после побега; город разыскивает беглеца неделю.</p><h3>Двери и живой мир</h3><p>В кузницу, трактир, лавку, склад, замок и дома можно войти прямо с улицы через южную дверь. Крыша исчезает только после входа, соседи за стеной остаются скрытыми. Торговцы работают внутри. Жители и рабочие ночью действительно возвращаются в свои дома.</p><h3>Собор и возвращение реликвий</h3><p>Вы начинаете во дворе. Западное крыло — библиотека с полками наставлений, бестиария, находок и хроник. Восточное — тренировки со стоячими и движущимися манекенами. Северное — зал Софоса. Верните ему реликвии: они появятся на пустых пьедесталах.</p><h3>Подземелья</h3><p>▾ на карте M — вход в пещеры: у тракта, в лесу или под водой. Подойдите вплотную и нажмите E. Внизу — разветвлённые туннели, тайники и враги; карта открывается при исследовании. Возвращайтесь к лестнице и нажмите E. Вещи после смерти остаются в том же подземелье; враги не возрождаются. Поверхность продолжает жить.</p><h3>Настоящее путешествие</h3><p>Регион 1280 × 960 клеток. Города далеко друг от друга; запасись едой и стрелами. На карте M можно выбрать пункт назначения. Подсказка покажет направление, расстояние и время ходьбы по прямой.</p><p>R — достать / убрать оружие; ЛКМ — направление удара или выбор цели для лука; пробел — атака (для лука по зафиксированной цели); ПКМ — снять захват; WASD / стрелки — движение; Shift — бег; ЛКМ / пробел — атака; Q — смена оружейного слота; E — взаимодействие; I — сумка; J — журнал; M — карта; H — библиотека; P — пауза; Повторная клавиша окна или клик снаружи — закрыть; Esc — закрыть любое окно. «Забрать всё рядом» собирает добычу и закрывает окно. Колесо мыши над миром — масштаб. F3 — счётчик кадров и времени расчётов. Esc или ☰ — меню: сохранение, пересоздание мира и debug-режим с быстрым перемещением на карте. Кнопка − сворачивает задания; Q и ↔ меняют оружие по двум слотам инвентаря.</p><p>Вода проходима вплавь, но скорость ниже. Река сносит на юг; в озере течения нет. Чем дальше от дороги, тем гуще лес и медленнее движение. Мосты позволяют перейти реку без плавания.</p><p>E у дерева с топором — рубить 6 секунд. E у трав или руды — собрать. Тушу животного нужно разделать, затем забрать добычу. Движение далеко от цели прерывает работу. После смерти появится экран итогов жизни. Затем в собор приходит новый человек без вещей и прежней репутации. Тело предшественника можно найти в мире, но стража не выдаст его имущество.</p>',bestiary:'<h3>Животные и противники</h3><p>'+Object.entries(ANIMALS).map(([key,a])=>a.name+' · '+a.hp+' здоровья · '+(a.aggressive?'опасен':'избегает людей')+(world.discovery.includes(key)?' · изучен':'')).join('<br>')+'</p><p>Разбойники, налётчики, громилы и лучники нападают на караваны. У лучников ограниченные стрелы; стены перекрывают выстрел. Стража и охрана караванов тоже используют луки.</p>',finds:'<h3>В дорожной сумке</h3><p>'+Object.keys(world.player.inventory).filter(k=>world.player.inventory[k]>0).map(k=>(ITEMS[k]?.icon||'◇')+' '+(ITEMS[k]?.name||k)).join('<br>')+'</p><p>Три реликвии находятся в руинах, кургане и святилище. Софос принимает каждую отдельно.</p>',world:'<h3>Профессии и дороги</h3><p>Рыбаки ловят рыбу и несут её на склад. Лесники рубят настоящие деревья, оставляя пни и складируя брёвна на месте. С 18:00 они грузят их и несут на городской склад; охотники убивают зверей, разделывают туши и доставляют мясо со шкурами. Рудокопы добывают руду. Кузнецы расходуют руду и дерево, трактирщики готовят из мяса и рыбы.</p><p>Обычный житель не торгует. Кузнец не покупает рыбу, рыбак не покупает меч. Караван действительно везёт товары, обменивает их со складом города и идёт дальше с охраной. Налёт может закончиться гибелью любой стороны. Погибшие не возрождаются.</p><p>Ночь: 20:00–06:00. Горожане возвращаются домой, стража остаётся. Один час равен примерно 92 секундам. Все окна приостанавливают симуляцию. Новый мир заменяет текущее автосохранение; старые сохранения переносят вещи в новый регион.</p>'};$('#codex').innerHTML=data[tab];}
function projectsPanel(city=world.inCity(world.player)?.id){openWindow('projects','<div id="projects-panel"></div>');renderProjects($('#projects-panel'),world,city,{notify:toast,changed:()=>{hud();save();},refresh:()=>projectsPanel(city)});}
function partyPanel(){openWindow('party','<div id="party-panel"></div>');renderPartyPanel($('#party-panel'),expedition.surface,{notify:toast,changed:()=>{hud();save();},refresh:partyPanel,surfacePresent:!world.dungeonSpec});}
function livingPanel(){openWindow('living','<div id="living-panel"></div>');renderLivingPanel($('#living-panel'),expedition.surface);}
function journal(){openWindow('journal','<div class="eyebrow">ПУТЕВОЙ ЖУРНАЛ</div><h1>Следы на дороге</h1><div class="quest-list"><h3>Реликвии Софоса · '+world.returnedRelics.length+'/'+relicCatalog(expedition.surface).length+'</h3><p>Софос просит возвращать находки целиком. Подробности поиска и зарисовки открываются отдельно.</p>'+world.quests.map(q=>'<article class="quest-entry"><span class="eyebrow">'+({active:'В РАБОТЕ',completed:'ЗАВЕРШЕНО',failed:'ПРОВАЛЕНО'})[q.status]+' · '+q.reward+' ЗОЛ.</span><h3>'+q.title+'</h3><p>'+world.questText(q)+'<br>Заказчик: '+(ROLES[q.giver]||'')+' · '+world.factionName(q.city)+'</p></article>').join('')+'</div><h3>Репутация и память городов</h3>'+world.cities.map(z=>{const m=cityMemory(world,z.id),r=warrant(world,z.id);return '<article class="quest-entry"><h3>'+z.name+' · '+m.reputation+'</h3><p>'+(r?'Розыск: '+r.name+' · ещё '+Math.ceil(r.expires-world.time)+' игровых мин.':'Розыска нет')+'</p>'+m.history.slice(0,5).map(h=>'<p>'+h.name+' · '+({wanted:h.expires>world.time?'разыскивается':'забыто',fine:'штраф уплачен',releasedWithoutMoney:'отпущен без денег',imprisoned:'заключение'})[h.status]+'</p>').join('')+'</article>';}).join('')+'<h3>Караваны</h3><p>Доставок: '+world.caravanStats.arrived+' · Потеряно обозов: '+world.caravanStats.lost+'</p><h3>Территории</h3><p>'+world.territories.map(z=>z.name+' — '+world.factionName(z.owner)).join('<br>')+'</p><h3>'+(world.debugMode?'Всемирная хроника · DEBUG':'Замеченные события')+'</h3><div class="codex">'+world.events.filter(e=>world.debugMode||world.eventObservable(e)).slice(0,35).map(e=>'<p>'+formatTime(e.time)+' · '+e.text+'</p>').join('')+'</div>');$('#modal-content').prepend(button('Поручения Софоса',relicJournal),button('Зарисовки и следы',observationNotes));if(expedition.surface.campaign)$('#modal-content').prepend(button('Колокол и рассвет · сюжет и подсказки · T',campaignPanel));}
function map(){if(world.dungeonSpec)return dungeonMap();mapOpen=true;openWindow('map','<div class="eyebrow">КАРТОГРАФИЯ · ЗЕРНО '+String(world.seed).replace(/[<>&"']/g,'')+(world.debugMode?' · DEBUG':'')+'</div><h1>'+ (world.regionName||'Большие Южные земли') +'</h1><canvas id="bigmap" width="800" height="600" style="width:100%;border:1px solid #c5ae7830"></canvas><div class="map-destinations" id="destinations"></div><div id="debug-travel"></div><p id="map-info">Выберите место или точку карты для ориентира.'+(world.debugMode?' В debug-режиме кнопка ниже позволяет мгновенно переместиться.':' Быстрое перемещение отключено.')+'</p>');const canvas=$('#bigmap');const refresh=()=>{renderMap(canvas.getContext('2d'),800,600,true);$('#debug-travel').replaceChildren();if(world.debugMode){const b=button('DEBUG · Переместиться'+(mapTarget?' → '+mapTarget.name:''),()=>{const result=world.debugTravel(mapTarget);if(!result.ok){toast(result.message);return;}camera.x=world.player.x;camera.y=world.player.y;nearest=null;close();findNearest();hud();toast('Быстрое перемещение выполнено');});b.className='debug-travel';b.disabled=!mapTarget;$('#debug-travel').append(b);}};const select=(target)=>{mapTarget=target;$('#map-info').textContent='Цель: '+target.name+' · '+travelText(target)+'.';refresh();};if(world.debugMode)for(const [kind,label]of [['herb','DEBUG · ближайшие травы'],['ore','DEBUG · ближайшая руда']])$('#destinations').append(button(label,()=>{const r=world.resources.filter(r=>r.kind===kind&&r.amount>0&&!world.blocked(r.x,r.y,true)).sort((a,b)=>dist(a,world.player)-dist(b,world.player))[0];if(r)select({name:ITEMS[kind].name,x:r.x,y:r.y});else toast('Не осталось доступных ресурсов');}));for(const site of (world.workSites||[]).filter(s=>s.kind==='port'))$('#destinations').append(button(site.name,()=>select({name:site.name,x:site.x,y:site.y})));for(const d of world.dungeonEntrances||[])$('#destinations').append(button('▾ '+d.name+' · '+({caves:'пещеры',catacombs:'катакомбы',ruins:'руины'})[d.template||'caves']+(d.kind==='underwater'?' · под водой':''),()=>select({name:d.name,x:d.x,y:d.y})));for(const camp of world.camps||[])$('#destinations').append(button('⌂ '+camp.name,()=>select(camp)));for(const site of world.workSites.filter(s=>['grainFarmer','beekeeper'].includes(s.kind)))$('#destinations').append(button(site.name+' · '+world.factionName(site.city),()=>select(site)));for(const prison of world.prisons||[]){const b=world.buildings[prison.buildingId-1];$('#destinations').append(button('⚿ '+b.name+' · '+world.factionName(prison.city),()=>select({name:b.name,...b.entrance})));}if(world.libraryShelves?.length)$('#destinations').append(button('План собора',sanctuaryPlan));for(const city of world.places.filter(z=>['oak','salt','north'].includes(z.id)))$('#destinations').append(button('План: '+city.name,()=>cityPlan(city)));for(const z of world.places)$('#destinations').append(button(z.name,()=>select({name:z.name,x:z.x*TILE,y:z.y*TILE})));canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),scale=Math.min(r.width/canvas.width,r.height/canvas.height),ox=(r.width-canvas.width*scale)/2,oy=(r.height-canvas.height*scale)/2,x=(e.clientX-r.left-ox)/scale,y=(e.clientY-r.top-oy)/scale;if(x<0||y<0||x>canvas.width||y>canvas.height)return;const tx=Math.min(W-2,Math.max(1,Math.floor(x/canvas.width*W))),ty=Math.min(H-2,Math.max(1,Math.floor(y/canvas.height*H)));select({name:'Точка '+tx+', '+ty,x:(tx+.5)*TILE,y:(ty+.5)*TILE});};refresh();}

function travelText(p){const d=dist(world.player,p);const seconds=Math.ceil(d/WALK_SPEED);return Math.round(d/TILE)+' кл. · от '+Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0')+' пешком';}
function activateLayer(){pathService?.dispose();assets?.dispose();world=expedition.current;connect();assets=new RenderAssets(world);pathService=new PathService(world);camera={x:world.player.x,y:world.player.y};keys={};nearest=null;mapTarget=null;mapCache=null;world.rebuildSpatial();world.update(0);hud();save();}
function enterDungeon(id,debug=false){const result=expedition.enter(id,{debug});if(!result.ok){toast(result.message);return;}close();activateLayer();toast('Подземелье: '+world.dungeonSpec.name);}
function interact(){if(!started||modal)return;if((world.player.stunUntil||0)>world.elapsed){toast('Вы оглушены.');return;}findNearest();if(!nearest)return;const n=nearest;if(n.kind==='loreSite'){observation(n.obj);return;}if(n.kind==='camp'){campWindow(n.obj);return;}if(n.kind==='contractBoard'){contracts(n.obj.city);return;}if(n.kind==='arrest'){arrestDialog();return;}if(n.kind==='cell'){cellDialog(n.obj);return;}if(n.kind==='prisonChest'){toast(recoverPrisonInventory(world,n.obj.city).message);hud();save();return;}if(n.kind==='dungeonEntrance'){enterDungeon(n.obj.id);return;}else if(n.kind==='dungeonExit'){expedition.leave();activateLayer();return;}else if(n.kind==='libraryShelf'){campaignEvent(world,'shelf');library(n.obj.tab);}else if(n.kind==='pedestal')open('<div class="eyebrow">ЗАЛ ВОЛШЕБНИКА</div><h1>'+n.obj.name+'</h1><p>'+(world.relicVault[n.obj.item]?'Реликвия возвращена Софосу и хранится на этом пьедестале.':'Пьедестал пуст. Найдите реликвию и передайте её Софосу.')+'</p>');else if(n.kind==='library')library();else if(n.kind==='landmark')loot(n.obj);else if(n.kind==='tree'){if(!world.player.inventory.axe){toast('Для рубки нужен топор');return;}world.player.action={type:'tree',id:n.obj.id,remaining:world.player.inventory.tools>0?4.8:6};toast('Рубка дерева · 6 секунд');}else if(n.kind==='resource'){if(beginGather(world,n))toast('Сбор: '+ITEMS[n.obj.kind].name);}else if(n.kind==='corpse'||n.kind==='woodPile')loot(n.obj);else{const e=n.obj;if(e.role==='wizard')wizard();else if(e.role==='dummy')toast('ЛКМ / пробел — удар; Q — смена оружия');else if(['red','ash','thorn'].includes(e.faction))toast('Разбойник обнажает оружие. Разговора не будет.');else if(TRADE[e.role]&&!e.noTrade)trade(e);else townTalk(e);}}

$('#begin-campaign').onclick=()=>{try{const old=localStorage.getItem(SAVE_KEY);if(old)localStorage.setItem(SAVE_KEY+'-before-regeneration',old);}catch{toast('Не удалось сохранить резервную копию. Запуск отменён.');return;}start(false,{campaign:true,forceCathedral:true});};
$('#crafting').onclick=()=>toggleWindow('craft',crafting);mini.onclick=()=>toggleWindow('map',map);
$('#attack').onclick=()=>{if(started&&!paused&&!modal)playerAttack();};$('#draw-weapon').onclick=()=>{if(started&&!paused&&!modal){const result=world.toggleWeapon();toast(result.message);hud();}};$('#interact').onclick=()=>toggleWindow('interaction',interact);$('#weapon-switch').onclick=switchWeapon;$('#menu').onclick=()=>toggleWindow('menu',gameMenu);$('#quest-toggle').onclick=()=>setJournalCollapsed(!journalCollapsed);$('#inventory').onclick=()=>toggleWindow('inventory',inventory);$('#help').onclick=()=>toggleWindow('library',()=>library());$('#journal').onclick=()=>toggleWindow('journal',journal);$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶':'Ⅱ';};
function setJournalCollapsed(value){journalCollapsed=!!value;$('.quest-panel').classList.toggle('collapsed',journalCollapsed);$('#quest-toggle').textContent=journalCollapsed?'+':'−';$('#quest-toggle').setAttribute('aria-expanded',String(!journalCollapsed));$('#quest-toggle').setAttribute('aria-label',journalCollapsed?'Показать задания':'Скрыть задания');try{localStorage.setItem('ashen-road-journal-collapsed',String(journalCollapsed));}catch{}}
function gameMenu(){if(!started)return;openWindow('menu','<div id="conversation"></div>');const primary=[{label:'Продолжить путешествие',run:()=>{paused=false;$('#pause').textContent='Ⅱ';close();}},{label:'Сохранить',run:say=>{save();say('Путешествие сохранено.');}}];if(expedition.surface.campaign?.status==='active')primary.push({label:'Текущая глава · T',run:campaignPanel});renderConversation($('#conversation'),{eyebrow:'ПЕПЕЛЬНЫЙ ТРАКТ · 0.27',title:'Меню путешествия',greeting:'Мир приостановлен.',primary,topics:[{id:'panels',label:'Разделы',render:body=>{const list=document.createElement('div');list.className='conversation-actions';for(const[label,fn]of [['Карта · M',map],['Журнал · J',journal],['Ремесло · C',crafting],['Доска заказов · B',()=>contracts()],['Пульс региона · N',livingPanel],['Спутники · V',partyPanel],['Проекты города · O',()=>projectsPanel()],['История кампании · T',campaignPanel]])list.append(button(label,fn));body.append(list);}},{id:'new',label:'Новая игра',render:body=>{const p=document.createElement('p');p.textContent='Новый мир заменит текущее путешествие. Перед запуском будет создана резервная копия.';body.append(p,button('Мир с обучающей кампанией',()=>regenerationMenu(true)),button('Свободный мир без обучения',()=>regenerationMenu(false)));}},{id:'settings',label:'Настройки',render:body=>{body.innerHTML='<div class="menu-settings"><label><input id="journal-setting" type="checkbox" '+(journalCollapsed?'checked':'')+'> Свернуть задания на экране</label><label><input id="debug-setting" type="checkbox" '+(world.debugMode?'checked':'')+'> Debug-режим <small>Открывает быстрое перемещение на карте.</small></label></div>';$('#debug-setting').onchange=e=>{world.debugMode=e.target.checked;hud();};$('#journal-setting').onchange=e=>setJournalCollapsed(e.target.checked);}}]});}

function migrationMenu(){open('<div class="eyebrow">НОВЫЙ РЕГИОН</div><h1>Путешествие из прежней версии</h1><p>География изменилась: карта стала вчетверо больше. Для продолжения в новом регионе можно перенести вещи, имя и ремесленные навыки странника. Задания, города и состояние прежнего мира при этом начнутся заново. Полный прежний снимок останется в отдельной резервной копии браузера.</p><div id="migration-actions" class="actions"></div>');$('#migration-actions').append(button('Сохранить копию и перенести странника',()=>{try{localStorage.setItem(SAVE_KEY+'-before-lore',localStorage.getItem(SAVE_KEY));}catch{toast('Не удалось создать копию. Перенос отменён.');return;}start(true,{migrate:true});}),button('Отмена · оставить сохранение',close));}
function newSeed(){return String(crypto.getRandomValues(new Uint32Array(1))[0]);}
function regenerationMenu(campaign=false){openWindow('menu','<div class="eyebrow">НОВОЕ ПУТЕШЕСТВИЕ</div><h1>'+(campaign?'Начать обучающую кампанию':'Пересоздать мир без обучения')+'</h1><p>'+(campaign?'Чистый мир с историей «Колокол и рассвет»: от уроков в соборе до возвращения артефакта. ':'Свободная игра без обучающих заданий. ')+'Новая генерация сбросит инвентарь, задания, время, добытые ресурсы, NPC и состояние караванов. Вы начнёте во дворе собора. Последнее состояние сохранится в отдельной резервной копии.</p><label class="seed-control">Зерно нового мира<input id="regenerate-seed" maxlength="32"></label><div class="actions"><button class="action" id="random-seed">Другое зерно</button><button class="action danger" id="regenerate-confirm">'+(campaign?'Начать кампанию в чистом мире':'Пересоздать и начать заново')+'</button><button class="action" id="regenerate-cancel">Отмена</button></div>');$('#regenerate-seed').value=newSeed();$('#random-seed').onclick=()=>$('#regenerate-seed').value=newSeed();$('#regenerate-cancel').onclick=gameMenu;$('#regenerate-confirm').onclick=()=>{const seed=$('#regenerate-seed').value.trim()||newSeed();try{localStorage.setItem(SAVE_KEY+'-before-regeneration',expedition.save());}catch{toast('Не удалось сохранить резервную копию. Сброс отменён.');return;}$('#regenerate-confirm').disabled=true;$('#regenerate-confirm').textContent='Создание мира…';requestAnimationFrame(()=>setTimeout(()=>{start(false,{seed,forceCathedral:true,campaign});toast((campaign?'Начата обучающая кампания':'Создан свободный мир')+' · зерно '+seed);},0));};}
