function inputKey(e){return ({KeyT:'t',KeyO:'o',KeyN:'n',KeyV:'v',KeyR:'r',KeyC:'c',KeyB:'b',KeyX:'x',KeyW:'w',KeyA:'a',KeyS:'s',KeyD:'d',KeyE:'e',KeyI:'i',KeyH:'h',KeyJ:'j',KeyM:'m',KeyP:'p',KeyQ:'q'})[e.code]||e.key.toLowerCase();}
addEventListener('keydown',e=>{const k=inputKey(e);if(expedition.surface.deathReport&&!expedition.surface.deathReport.acknowledged){if(!e.target.closest('#death-report'))e.preventDefault();return;}if(k==='escape'){e.preventDefault();if(!started||e.repeat)return;if(modal)close();else gameMenu();return;}if(e.target.matches('input:not([type=checkbox]):not([type=button]),textarea,[contenteditable=true]'))return;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(!started||e.repeat)return;const windows={t:['campaign',campaignPanel],o:['projects',()=>projectsPanel()],v:['party',partyPanel],n:['living',livingPanel],c:['craft',crafting],b:['contracts',()=>contracts()],i:['inventory',inventory],h:['library',()=>library()],j:['journal',journal],m:['map',map],e:['interaction',interact]};if(windows[k]){e.preventDefault();toggleWindow(...windows[k]);return;}if(modal)return;keys[k]=true;if(k==='-'||k==='=')zoom=Math.max(.25,Math.min(1.5,zoom*(k==='-'?.8:1.25)));if(k==='f3'){e.preventDefault();debugPerf=!debugPerf;$('#performance').classList.toggle('hidden',!debugPerf);}if(k==='r'){$('#draw-weapon').click();}if(k==='q')switchWeapon();if(k==='x'&&cancelCraft(world))toast('Работа отменена. Материалы возвращены.');if(k==='p')$('#pause').click();if(k===' '&&!paused)playerAttack();});addEventListener('keyup',e=>keys[inputKey(e)]=false);addEventListener('blur',()=>{keys={};if(started)save();});canvas.addEventListener('pointermove',e=>{mouse={x:e.clientX,y:e.clientY,active:true};});canvas.addEventListener('pointerdown',e=>{if(!started||paused||modal)return;mouse={x:e.clientX,y:e.clientY,active:true};if(e.button===2){world.player.lockedTargetId=null;return;}if(e.button!==0)return;if(!world.player.weaponDrawn)return;world.aimPlayer(mouseWorld(),{lock:true});keys.mouseAttack=true;playerAttack();});canvas.addEventListener('click',e=>{if(!started||paused||modal||world.player.weaponDrawn||e.button!==0)return;mouse={x:e.clientX,y:e.clientY,active:true};const target=hoveredNpc(world,mouseWorld(),zoom);if(target&&!ANIMALS[target.role]&&!['dummy','bandit','banditArcher','brute','raider','nomad','nomadArcher'].includes(target.role)&&world.canInteract(world.player,target,155)){if(target.role==='wizard')wizard();else if(TRADE[target.role]&&!target.noTrade)trade(target);else townTalk(target);}else if(target)toast('Подойдите ближе к собеседнику.');});addEventListener('pointerup',()=>keys.mouseAttack=false);canvas.addEventListener('contextmenu',e=>e.preventDefault());addEventListener('beforeunload',()=>{if(started)save();});
