function ellipse(x,y,rx,ry,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill();}function poly(points,fill,stroke){ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function building(b){if(drawLoreTent(ctx,b,world))return;if(b.type==='cage'){drawPrison(ctx,world,b);return;}const inside=world.interiorAt(world.player);if(b.enterable&&inside?.id===b.id&&b.type!=='cathedral'){drawInterior(ctx,b,world.night);if(b.prison)drawPrison(ctx,world,b);if(b.type==='dungeonGate'){const d=world.dungeonEntrances.find(d=>d.buildingId===b.id);if(d)drawPortal(d,false);}if(b.type==='wizardHall')drawRelicPedestals();if(b.type==='library')for(const shelf of world.libraryShelves)label(shelf.name,shelf.x,shelf.y-52,'#d8c497',9);return;}if(b.type==='cathedral'&&inside?.id!==b.id){closedCathedral(b);}else buildingExterior(b);if(b.enterable&&inside?.id!==b.id){drawDoor(ctx,b);if(dist(world.player,b.entrance)<210)label(roomName(b)+' · вход',(b.x+b.w/2)*TILE,(b.y+b.h-1.8)*TILE,'#d7c699',10);}}
