 for(const camp of world.camps||[]){c.fillStyle='#e7c078';c.font=(big?'16':'10')+'px system-ui';c.textAlign='center';c.fillText('⌂',camp.x/TILE*sx,camp.y/TILE*sy);if(big){c.font='9px system-ui';c.fillText(camp.name,camp.x/TILE*sx,camp.y/TILE*sy+12);}}
