function renderCaveMap(c,width,height){const b=world.dungeonBounds,scale=Math.min(width/b.w,height/b.h),ox=(width-b.w*scale)/2,oy=(height-b.h*scale)/2;c.fillStyle='#101315';c.fillRect(0,0,width,height);for(let y=b.y;y<b.y+b.h;y++)for(let x=b.x;x<b.x+b.w;x++){const i=y*W+x;if(!world.explored[i]&&!(world.debugMode&&world.debugMapReveal))continue;c.fillStyle=world.solids[i]?(world.tiles[i]===11?'#535f60':'#343438'):world.tiles[i]===2?'#416e82':world.tiles[i]===12?'#b5b2a1':world.tiles[i]===14?'#8a8170':world.visibleCells[i]?'#b29d78':'#666454';c.fillRect(ox+(x-b.x)*scale,oy+(y-b.y)*scale,scale+.3,scale+.3);}const marker=(p,color,size)=>{c.fillStyle=color;c.beginPath();c.arc(ox+(p.x/TILE-b.x)*scale,oy+(p.y/TILE-b.y)*scale,size,0,Math.PI*2);c.fill();};marker(world.dungeonExit,'#a8d0bc',width>200?5:2);for(const corpse of world.corpses)if(corpse.player)marker(corpse,'#d6a35e',width>200?4:2);marker(world.player,'#fff3c5',width>200?5:2);}
function drawPortal(d,exit){const x=d.x,y=d.y;if(d.buildingId){if(world.interiorAt(world.player)?.id!==d.buildingId)return;ctx.fillStyle='#17221e';ctx.fillRect(x-26,y-30,52,55);for(let j=0;j<6;j++){ctx.fillStyle=j%2?'#8b8873':'#6e7364';ctx.fillRect(x-24+j*2,y-24+j*9,48-j*4,6);}label('ЛЕСТНИЦА ВНИЗ · E',x,y-44,'#dfcda4',10);return;}if(!exit&&d.template&&d.template!=='caves'){ctx.fillStyle=d.template==='ruins'?'#6b7167':'#8b8878';ctx.fillRect(x-63,y-68,126,83);ctx.fillStyle='#17201c';ctx.fillRect(x-27,y-46,54,61);for(const side of [-1,1]){ctx.fillStyle='#aaa58b';ctx.fillRect(x+side*45-8,y-72,16,88);ctx.fillRect(x+side*45-13,y-77,26,9);}poly([[x-70,y-78],[x,y-111],[x+70,y-78]],'#858a79');if(d.template==='ruins'){poly([[x+10,y-90],[x+50,y-71],[x+25,y-30]],'#304538');}label(d.template==='ruins'?'ЗАТОПЛЕННЫЕ РУИНЫ':'КАТАКОМБЫ',x,y-126,'#d8c6a0',10);return;}ellipse(x+4,y+10,64,25,'#09130e88');if(exit){ctx.fillStyle='#a3997c';for(let i=0;i<6;i++)ctx.fillRect(x-24+i*2,y+18-i*10,48-i*4,8);poly([[x-40,y-37],[x+40,y-37],[x+29,y-78],[x-28,y-78]],'#8e9078');label('НА ПОВЕРХНОСТЬ · E',x,y-94,'#d9d2a9',11);}else {const wet=d.kind==='underwater';poly([[x-66,y+9],[x-53,y-35],[x-24,y-65],[x+22,y-60],[x+56,y-26],[x+68,y+12]],wet?'#536d72':'#737365');ellipse(x,y-9,35,33,'#101a1b');ctx.strokeStyle=wet?'#86b7bd':'#aa9c7e';ctx.lineWidth=5;ctx.beginPath();ctx.arc(x,y-7,37,Math.PI,Math.PI*2);ctx.stroke();if(wet){ellipse(x,y+7,54,12,'#83b2b94d');for(let i=0;i<3;i++)ellipse(x+18+i*8,y-50-i*17,3,3,'#b2d6d5');}else{ctx.fillStyle='#ab8758';ctx.fillRect(x-52,y-13,6,29);ellipse(x-49,y-23,7,13,'#d8aa59');}if(dist(d,world.player)<440)label(d.name+(wet?' · под водой':''),x,y-87,'#dbcb9e',11);}}
function drawCaveFog(left,right,top,bottom){for(let y=Math.max(0,Math.floor(top/TILE));y<=Math.min(H-1,Math.ceil(bottom/TILE));y++)for(let x=Math.max(0,Math.floor(left/TILE));x<=Math.min(W-1,Math.ceil(right/TILE));x++){const i=y*W+x;if(world.visibleCells[i])continue;ctx.fillStyle=world.explored[i]?'#060c10e6':'#080c0f';ctx.fillRect(x*TILE,y*TILE,TILE+1,TILE+1);}}
function drawRelicPedestals(){for(const p of world.pedestals||[]){const x=p.display.x,y=p.display.y;if(world.relicVault[p.item]>0){ellipse(x,y-25,15,7,'#c9b37144');ctx.fillStyle='#e0d09b';ctx.font='27px Georgia';ctx.textAlign='center';ctx.fillText(ITEMS[p.item].icon,x,y-22);}else label('ПУСТО',x,y-20,'#b0aa8e',8);}}
function sanctuaryPlan(){const z=world.places.find(z=>z.id==='cathedral');openWindow('map','<div class="eyebrow">СОБОР ПОСЛЕДНЕГО СВЕТА</div><h1>Двор и три крыла</h1><canvas id="city-plan" width="720" height="620" style="width:100%"></canvas><p>Слева — четыре библиотечные полки; справа — стоячие и подвижные манекены. Северное крыло — Софос и девять пьедесталов. Южные ворота ведут на подъездную дорогу.</p><div id="sanctuary-destinations" class="actions"></div>');const c=$('#city-plan').getContext('2d'),scale=10,ox=z.x-36,oy=z.y-31;c.imageSmoothingEnabled=false;c.drawImage(baseMap(),ox,oy,72,62,0,0,720,620);for(const b of world.buildings.filter(b=>b.sanctuary&&b.enterable)){c.fillStyle='#20352c';c.font='bold 11px system-ui';c.textAlign='center';c.fillText(b.name,(b.x+b.w/2-ox)*scale,(b.y+b.h/2-oy)*scale);}c.fillStyle='#fff0b7';c.beginPath();c.arc((world.player.x/TILE-ox)*scale,(world.player.y/TILE-oy)*scale,5,0,Math.PI*2);c.fill();const targets=[{name:'Двор',...world.spawn},...world.buildings.filter(b=>b.sanctuary&&b.enterable).map(b=>({name:b.name,...(world.debugMode?b.workSpot:b.entrance)}))];for(const target of targets)$('#sanctuary-destinations').append(button((world.debugMode?'DEBUG · ':'')+target.name,()=>{if(world.debugMode){const result=world.debugTravel(target);if(!result.ok)return toast(result.message);camera={x:world.player.x,y:world.player.y};}else mapTarget=target;close();}));}
function drawLogPile(p){const n=Math.min(12,p.inventory.log);for(let i=0;i<n;i++){const x=p.x+(i%4)*10-15,y=p.y-Math.floor(i/4)*8;ctx.fillStyle='#88704b';ctx.fillRect(x-18,y-6,36,9);ellipse(x+18,y-2,5,5,'#c2a575');ellipse(x+18,y-2,2,2,'#86673f');}if(dist(p,world.player)<160)label('Брёвна × '+p.inventory.log,p.x,p.y-36,'#d4bf8f',9);}
function speechBubble(e){ctx.font='10px Manrope,system-ui';const words=(e.announcement||'').split(' '),lines=[];let line='';for(const word of words){if(ctx.measureText(line+' '+word).width>235&&line){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);const x=e.x,y=e.y-80-lines.length*15;ctx.fillStyle='#14231de8';ctx.strokeStyle='#b8a47077';ctx.fillRect(x-130,y,260,lines.length*15+18);ctx.strokeRect(x-130,y,260,lines.length*15+18);ctx.fillStyle='#ded4b2';ctx.textAlign='center';lines.forEach((t,i)=>ctx.fillText(t,x,y+17+i*15));}
